Ext.define('BNK.view.HumanResource.hrp.HrpOgiDept01MViewController', {
    extend: 'BaseViewController',
    alias: 'controller.humanresource.hrp.hrpogidept01m',

    config: {
        viewId: 'HrpOgiDept01M'
    },

    onSelect: function() {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences(),
            store = me.getStore('EMPINFOStore');

        var codelist = [];
        codelist.push();

        var hrHrpmDeptId = vm.get('hrHrpmDeptId');

        var params = {
            hrHrpmDeptId : hrHrpmDeptId == 999 ? '': hrHrpmDeptId,
            hdqDeptId : vm.get('hdqDeptId'),
            empeNm : refs.nameTxt.getValue(),
            wkingDvcdList : [Constants.wkingDvcd.WORK_NORMAL,
                             Constants.wkingDvcd.WORK_CONCURRENT,
                             Constants.wkingDvcd.WORK_DISPATCH],
            noPaging : true,
            searchDate : DateUtils.getDate(new Date()) //금일 기준으로 검색
        };

        console.log('hrHrpmDeptId : ' + params.hrHrpmDeptId);
        console.log('hdqDeptId    : ' + params.hdqDeptId);

        store.getProxy().extraParams = params;
        store.removeAll();
        store.loadPage(1);

    },

    /* 돋보기 조회 버튼 탭 이벤트 */
    onSearchTap: function(button, e, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        var hrHrpmDeptId = refs.searchDept.getSelection().data.hrHrpmDeptId,
            hdqDeptId = refs.searchDept.getSelection().data.hdqDeptId,
            upperDeptId = refs.searchDept.getSelection().data.upperDeptId;

        if(hrHrpmDeptId === hdqDeptId){
            vm.set('hdqDeptId', hdqDeptId);
            vm.set('hrHrpmDeptId', null);
        } else {
            if(upperDeptId === 0){
                vm.set('hdqDeptId', null);
                vm.set('hrHrpmDeptId', null); // BNK시스템 선택 시 전체 조회
            } else {
                vm.set('hdqDeptId', hdqDeptId);
                vm.set('hrHrpmDeptId', hrHrpmDeptId);
            }
        }

        this.onSelect();
    },

    /* 부서 조회 */
    onDeptSelect: function(combobox, newValue, oldValue, eOpts) {
        var me = this,
            vm = me.getViewModel(),
            refs = me.getReferences();

        // 선택한 부서의  ID,  본부부서ID,  상위부서ID
        var hrHrpmDeptId = newValue.data.hrHrpmDeptId,
            hdqDeptId = newValue.data.hdqDeptId,
            upperDeptId = newValue.data.upperDeptId;

        if(hrHrpmDeptId === hdqDeptId){
            vm.set('hdqDeptId', hdqDeptId);
            vm.set('hrHrpmDeptId', null);
        } else {
            if(upperDeptId === 0){
                vm.set('hdqDeptId', null);
                vm.set('hrHrpmDeptId', null); // BNK시스템 선택 시 전체 조회
            } else {
                vm.set('hdqDeptId', hdqDeptId);
                vm.set('hrHrpmDeptId', hrHrpmDeptId);
            }
        }

        me.onSelect();

    },

    /* 사원 탭 -> 사원 상세정보 보기 */
    onGridEmpInfoClick: function(dataview, selected, eOpts) {
        var me = this;
        var vm = me.getViewModel();

        var win = Ext.create('HrpOgiDept51M', selected[0].data);
        // 팝업창에서 이벤트 호출시 실행되는 함수
        me.mon(win, 'selected', function(data, popup) {

        }, this);

        win.show(); // 팝업창표시
    },

    initialize: function(component, eOpts) {
        var me = this,
            refs = me.getReferences();

        // 부서 콤보박스 조회 // Controller 에 extend BaseViewController
        me.GET_CODELIST({
            stcd : '01' ,
            codeDvcd : 'DEPTLV'
        }).then(function(records) {
            var store = me.getViewModel().get('DeptStore');
            store.add({text : "- 전  체 -", value : 999});
            store.add(records.data);
            refs.searchDept.setValue(SecurityUtils.getPrincipal().hrHrpmDeptId);
            me.onSelect();
        });

        // Hidden Grid Header
        refs.grdToolbar.el.select('.x-headercontainer').setStyle('height',	'0px');

    }

});